create table if not exists public.record_relief_monitor_auth(id boolean primary key default true check(id),token uuid not null default gen_random_uuid(),created_at timestamptz not null default now(),rotated_at timestamptz not null default now()); alter table public.record_relief_monitor_auth enable row level security; revoke all on table public.record_relief_monitor_auth from public,anon,authenticated; grant select,insert,update,delete on table public.record_relief_monitor_auth to service_role; insert into public.record_relief_monitor_auth(id) values(true) on conflict(id) do nothing;